	/**
	 * Default Constructor
	 */
    public BIQueryService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new BIQueryEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(BIQueryRepository.class) );
		this.validator		= applicationContext.getBean(BIQueryValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		BIQuery
	 */
		public BIQuery createBIQuery( CreateBIQueryCommand command ) {

		BIQuery entity = new BIQuery();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setBIQueryId( command.getBIQueryId() );
            entity.setName( command.getName() );
            entity.setText( command.getText() );
            entity.setDialect( command.getDialect() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of BIQuery {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateBIQueryCommand
	 * @return		BIQuery
	 */
	public BIQuery updateBIQuery( UpdateBIQueryCommand command ) {

		BIQuery entity = new BIQuery();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setBIQueryId( command.getBIQueryId() );
            entity.setName( command.getName() );
            entity.setText( command.getText() );
            entity.setWorkspace( command.getWorkspace() );
            entity.setDatasets( command.getDatasets() );
            entity.setReports( command.getReports() );
            entity.setDashboards( command.getDashboards() );
            entity.setNotebooks( command.getNotebooks() );
            entity.setDialect( command.getDialect() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of BIQuery {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteBIQueryCommand
	 */
	public void delete( DeleteBIQueryCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getBIQueryId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of BIQuery {0} ", id );

	}

	/**
	 * Method to retrieve the BIQuery via BIQueryFetchOneSummary
	 * @param 	summary BIQueryFetchOneSummary
	 * @return 	BIQueryFetchOneResponse
	 */
	public BIQuery getBIQuery( BIQueryFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "BIQueryFetchOneSummary arg cannot be null" );

		BIQuery entity = null;
		UUID id = summary.getBIQueryId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a BIQuery using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all BIQuerys
	 *
	 * @return 	List<BIQuery>
	 */
    public List<BIQuery> getAllBIQuery() {
		List<BIQuery> list = projector.findAll( new FindAllBIQueryQuery() );
		return list;
	}

	/**
	 * assign Workspace on BIQuery
	 * @param		command AssignWorkspaceToBIQueryCommand
	 */
	public void assignWorkspace( AssignWorkspaceToBIQueryCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignWorkspace(command.getBIQueryId(), command.getAssignment());

	}

